// lookup demo — Cheddar (jahdb demo program)
var DATA={"Cheddar":"Cheddar is the world favorite hard cheese: clothbound farmhouse for depth, block for melting. Ages from mild to extra-sharp."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("cow"));

